package com.tracksphere.infrastructure.security;
import com.tracksphere.domain.model.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final JwtProperties properties; private final SecretKey key; public JwtService(JwtProperties properties){this.properties=properties; if(properties.secret().getBytes(StandardCharsets.UTF_8).length<32) throw new IllegalStateException("APP_JWT_SECRET must be at least 32 bytes"); key=Keys.hmacShaKeyFor(properties.secret().getBytes(StandardCharsets.UTF_8));} public String createAccessToken(User user){Instant now=Instant.now(); return Jwts.builder().subject(user.getId().toString()).claim("email",user.getEmail()).claim("roles",user.getRoles().stream().map(r->r.getName()).toList()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(properties.accessTokenExpiration()))).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
